// ——— подписи словаря Sprut.Hub (правка после сборки сценариев) ——————————
//
// «Вот тут все типы сервисов перечислены, с их характеристиками… Перенеси эту
// структуру». Словарь имитации (`sim/catalog.js`) знает все несистемные
// сервисы хаба, и у каждого сервиса, характеристики и значения обязана быть
// подпись. Подписи хаба собраны из `sh_types.json` блоком ниже — его пишет
// `node tools/hub-types.mjs`, руками его не правят, а пересобирают.
//
// Подписи, написанные выше руками (`strings.sim.services`, `chars`, `values`),
// **главнее**: блок добавляет только то, чего там нет. Так «Лампочка» и
// «Датчик открытия (геркон)» остаются нашими словами, а сотня новых сервисов и
// характеристик получает слова хаба.
