// </hub-labels>

for (const group of ["services", "chars"]) {
  for (const [key, label] of Object.entries(SIM_HUB_LABELS[group])) {
    if (!Object.prototype.hasOwnProperty.call(strings.sim[group], key)) strings.sim[group][key] = label;
  }
}
for (const [char, labels] of Object.entries(SIM_HUB_LABELS.values)) {
  strings.sim.values[char] = { ...labels, ...(strings.sim.values[char] || {}) };
}

// strings.errors.codeTaken и подобные — шаблоны с {переменными}.
export function text(key, vars) {
  let value = key.split(".").reduce((node, part) => (node == null ? node : node[part]), strings);
  if (typeof value !== "string") return key;
  if (vars) {
    for (const [name, replacement] of Object.entries(vars)) {
      value = value.split("{" + name + "}").join(String(replacement));
    }
  }
  return value;
}
